ret_t validate_user_credentials(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t result = ret_error;
    LDAPMessage *search_result = NULL;
    char *user_dn = NULL;

    if (ldap == NULL || conn == NULL) {
        return ret_error;
    }

    if (conn->username == NULL || conn->password == NULL) {
        return ret_not_found;
    }

    char filter[256];
    snprintf(filter, sizeof(filter), "(&(objectClass=inetOrgPerson)(uid=%s))", conn->username);

    if (ldap_search_s(ldap->ldap_handle, ldap->base_dn, LDAP_SCOPE_SUBTREE, filter, NULL, 0, &search_result) != LDAP_SUCCESS) {
        goto cleanup;
    }

    if (ldap_count_entries(ldap->ldap_handle, search_result) != 1) {
        result = ret_not_found;
        goto cleanup;
    }

    LDAPMessage *entry = ldap_first_entry(ldap->ldap_handle, search_result);
    user_dn = ldap_get_dn(ldap->ldap_handle, entry);
    if (user_dn == NULL) {
        goto cleanup;
    }

    if (ldap_bind_s(ldap->ldap_handle, user_dn, conn->password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
        result = ret_not_found;
    } else {
        result = ret_ok;
    }

cleanup:
    if (search_result != NULL) {
        ldap_msgfree(search_result);
    }

    if (user_dn != NULL) {
        ldap_memfree(user_dn);
    }

    ldap_unbind(ldap->ldap_handle);

    return result;
}

ret_t validate_user_credentials(cherokee_validator_ldap_t *ldap, cherokee_connection_t *conn) {
    ret_t result = ret_error;

    if (!ldap || !conn || !conn->user || !conn->password) {
        return ret_error;
    }

    char *search_filter = ldap_build_search_filter(ldap, conn->user);
    if (!search_filter) {
        return ret_error;
    }

    LDAPMessage *search_result = NULL;
    int ldap_rc = ldap_search_ext_s(ldap->connection, ldap->base_dn, LDAP_SCOPE_SUBTREE, search_filter, NULL, 0, NULL, NULL, LDAP_NO_LIMIT, LDAP_NO_LIMIT, &search_result);

    if (ldap_rc != LDAP_SUCCESS) {
        free(search_filter);
        return ret_error;
    }

    if (!search_result || ldap_count_entries(ldap->connection, search_result) != 1) {
        ldap_msgfree(search_result);
        free(search_filter);
        return ret_not_found;
    }

    LDAPMessage *entry = ldap_first_entry(ldap->connection, search_result);
    char *dn = ldap_get_dn(ldap->connection, entry);
    if (!dn) {
        ldap_msgfree(search_result);
        free(search_filter);
        return ret_error;
    }

    int auth_result = ldap_bind_s(ldap->connection, dn, conn->password, LDAP_AUTH_SIMPLE);
    ber_memfree(dn);

    if (auth_result != LDAP_SUCCESS) {
        result = ret_error;
    } else {
        result = ret_ok;
    }

    ldap_msgfree(search_result);
    free(search_filter);
    ldap_unbind_ext_s(ldap->connection, NULL, NULL);

