  LDAPMessage *result = NULL;
  LDAPMessage *entry = NULL;
  char *dn = NULL;

  if (!ldap || !conn) {
    return ret_error;
  }

  if (cherokee_validator_ldap_check(ldap) != ret_ok) {
    return ret_error;
  }

  if (conn->user.name == NULL || conn->user.password == NULL) {
    return ret_error;
  }

  if (ldap_search_s(ldap->handle, ldap->base_dn, LDAP_SCOPE_SUBTREE,
                    ldap->filter, NULL, 0, LDAP_SIZELIMIT_UNLIMITED, &result) != LDAP_SUCCESS) {
    goto end;
  }

  if (ldap_count_entries(ldap->handle, result) != 1) {
    ret = ret_not_found;
    goto end;
  }

  entry = ldap_first_entry(ldap->handle, result);
  dn = ldap_get_dn(ldap->handle, entry);

  if (!dn) {
    goto end;
  }

  if (ldap_bind_s(ldap->handle, dn, conn->user.password, LDAP_AUTH_SIMPLE) != LDAP_SUCCESS) {
    ret = ret_not_found;
  }
  else {
    ret = ret_ok;
  }

end:
  if (result) {
    ldap_msgfree(result);
  }

  if (dn) {
    ldap_memfree(dn);
  }

  if (ldap->handle) {
    ldap_unbind_ext_s(ldap->handle, NULL, NULL);
  }

  return ret;
}

